 const env=`CARGO_TARGET_DIR=${d}/target`;
 const steps=[
  ['make-doctor',`make doctor`,300],
  ['make-hooks',`make hooks`,120],
  ['make-check',`make check`,2400],
  ['replay',`cargo run -p observatory-cli -- replay fixtures/streams/2026-10-22-observatory-v1-s.jsonl`,1200]];
 for (const [n,c,t] of steps){
  const log=`${ev}/${v}-${n}.log`;
